# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, P, R, J, A = "Lucas", "Pepe", "Ramón", "Jordi", "Amparo"
D = [
("#", "Escena 1 · 9:00 · Sala de reuniones", "장면 1 · 오전 9시 · 회의실"),
(None, "Miércoles 26 de marzo. En la pizarra, Lucas ha dibujado una línea con cuatro paradas: Onda → Valencia → Altamira → Monterrey. Pepe llega con una carpeta de costes; Ramón, con su calculadora de siempre.", "3월 26일 수요일. 칠판에 루카스가 정거장 네 개짜리 선을 그려 놓았다. 온다 → 발렌시아 → 알타미라 → 몬테레이. 페페는 원가 서류철을, 라몬은 늘 쓰는 계산기를 들고 온다."),
(L, "Buenos días. Gracias por venir tan pronto.", "좋은 아침이에요. 일찍 와 줘서 고마워요."),
(P, "¿Pronto? Son las nueve. Yo estoy aquí desde las seis, como siempre.", "일찍? 9시야. 난 늘 그렇듯 6시부터 여기 있었어."),
(R, "No empecemos. Lucas, ¿qué es ese dibujo?", "시작하지 말자. 루카스, 그 그림은 뭐야?"),
(L, "El viaje de una baldosa: de nuestro almacén a la obra de Alejandra en San Pedro. Cada flecha es un coste.", "타일 한 장의 여행이에요. 우리 창고에서 산페드로의 알레한드라 공사 현장까지. 화살표 하나하나가 비용이에요."),
(P, "Muy bonito. Parece el mapa del metro de Madrid.", "예쁘네. 마드리드 지하철 노선도 같아."),
(R, "Con la diferencia de que en el metro el billete cuesta dos euros.", "차이점이라면 지하철 표는 2유로라는 거지."),
(L, "Vamos por partes. Pepe, empezamos por la fábrica. ¿Cuánto nos cuesta fabricar un metro cuadrado del mármol blanco en sesenta por ciento veinte?", "하나씩 가죠. 페페, 공장부터 시작해요. 60×120 흰 대리석 타일 1㎡를 만드는 데 얼마가 들어요?"),
(P, "Coste completo, con gas, arcilla, esmalte, mano de obra y amortización: nueve euros con cuarenta el metro.", "가스, 점토, 유약, 인건비, 감가상각까지 다 넣은 총원가로 ㎡당 9유로 40센트."),
(R, "Nueve cuarenta con el gas de este trimestre. Si el gas sube, sube.", "이번 분기 가스 가격 기준 9.40이야. 가스가 오르면 같이 올라."),
(L, "Entendido. ¿Y a qué precio lo vendemos en España?", "알겠어요. 스페인에선 얼마에 팔아요?"),
(R, "Tarifa oficial, dieciséis cincuenta. Pero nadie paga tarifa. A BricoHogar se lo dejamos a doce ochenta.", "공식 가격표는 16.50. 하지만 아무도 가격표대로 안 내. 브리코오가르에는 12.80에 줘."),
(L, "¿Doce ochenta? Es un margen muy pequeño.", "12.80이요? 마진이 아주 작네요."),
(R, "Y si les damos el cuatro por ciento que piden, se queda en doce veintinueve.", "그리고 그쪽이 요구하는 4%를 주면 12.29가 돼."),
(P, "Por eso tenemos el horno tres parado. Fabricar para perder dinero no tiene sentido.", "그래서 3호기를 세워 둔 거야. 돈 잃으려고 생산하는 건 말이 안 되니까."),
(L, "Bien. Ramón, ¿cuál es el precio mínimo en fábrica para que una venta merezca la pena?", "좋아요. 라몬, 판매할 가치가 있으려면 공장 출고 최저가가 얼마예요?"),
(R, "Por debajo de doce cincuenta en fábrica, no vendo ni una caja. Ese es mi suelo. Y nunca mejor dicho.", "공장 출고가 12.50 아래면 한 상자도 안 팔아. 그게 내 바닥이야. 말 그대로."),
(L, "(escribe en la pizarra) «Suelo: 12,50». ¿Y el precio que nos gustaría?", "(칠판에 적으며) '바닥: 12.50'. 그럼 받고 싶은 가격은요?"),
(R, "El que nos gustaría es dieciséis cincuenta. El realista, no lo sé. Dímelo tú.", "받고 싶은 건 16.50이지. 현실적인 가격은 모르겠어. 네가 말해 봐."),
(L, "Para exportación propongo trece veinte en fábrica. Es decir, precio EXW Onda.", "수출용으로는 공장 출고가 13.20을 제안해요. 즉 EXW 온다 가격이요."),
(P, "¿EXW? Habla en cristiano, hombre.", "EXW? 알아듣게 말해, 이 사람아."),
(L, "Ex Works: en fábrica. El cliente viene a buscar la mercancía a nuestra puerta y se encarga de todo lo demás.", "엑스 웍스, 공장 인도요. 고객이 우리 공장 문 앞까지 물건을 가지러 오고 나머지는 전부 알아서 하는 거예요."),
(P, "Ah, como los camioneros franceses. Esos vienen, cargan y se van.", "아, 프랑스 트럭 기사들처럼. 와서 싣고 가 버리지."),
(L, "Exacto. Pero Alejandra no va a mandar un camión desde Monterrey. Ella quiere el precio puesto en Monterrey.", "맞아요. 근데 알레한드라가 몬테레이에서 트럭을 보낼 리는 없죠. 그녀는 몬테레이 도착 기준 가격을 원해요."),
(R, "Lo que significa que todo lo que hay entre aquí y allí lo pagamos nosotros.", "그 말은 여기서 거기까지 사이에 있는 걸 전부 우리가 낸다는 거지."),
(L, "Lo pagamos nosotros y se lo cobramos a ella. Pero hay que calcularlo bien. Si nos equivocamos, el error sale de nuestro margen.", "우리가 내고 그녀에게 청구하는 거예요. 하지만 정확히 계산해야 해요. 틀리면 그 오차는 우리 마진에서 나가요."),
(P, "¿Y el embalaje? Para un viaje así no vale el palé de siempre.", "포장은? 그런 여행엔 평소 팔레트로는 안 돼."),
(L, "¿Qué hace falta?", "뭐가 필요해요?"),
(P, "Palés de madera tratada, con el sello de la norma internacional; si no, en la aduana mexicana no los dejan pasar. Cantoneras, más film, flejes dobles. Unos veinticinco céntimos más por metro.", "국제 규격 도장이 찍힌 열처리 목재 팔레트. 안 그러면 멕시코 세관에서 통과를 안 시켜 줘. 모서리 보호대, 랩 추가, 이중 밴딩. ㎡당 25센트쯤 더 들어."),
(L, "Apuntado. Trece veinte más veinticinco céntimos: trece cuarenta y cinco antes de salir de Onda.", "적었어요. 13.20에 25센트를 더하면 온다를 나서기 전에 13.45."),
(R, "Y no te olvides del coste financiero. Si cobramos a sesenta días, el dinero también cuesta.", "금융 비용도 잊지 마. 60일 뒤에 돈을 받으면 돈에도 비용이 들어."),
(L, "Por eso queremos un treinta por ciento de anticipo. Lo hablamos el lunes.", "그래서 선수금 30%를 원하는 거예요. 월요일에 얘기했잖아요."),
(R, "Lo hablamos. No lo aprobamos.", "얘기는 했지. 승인은 안 했어."),
(P, "Ya estamos. ¿Llamamos al del puerto o no?", "또 시작이네. 항구 사람한테 전화할 거야 말 거야?"),

("#", "Escena 2 · 11:30 · Sala de reuniones · Llamada con el puerto de Valencia", "장면 2 · 오전 11시 30분 · 회의실 · 발렌시아 항구와 통화"),
(None, "Lucas pone el móvil en manos libres en el centro de la mesa. Al otro lado está Jordi Bosch, de una empresa transitaria del puerto de Valencia. Se oyen grúas y bocinas de camiones.", "루카스가 휴대폰을 스피커 모드로 해서 탁자 가운데에 놓는다. 전화 너머에는 발렌시아 항구의 운송주선업체 직원 조르디 보스크가 있다. 크레인 소리와 트럭 경적이 들린다."),
(J, "Bon dia, Lucas! ¿Me oís bien? Estoy en la terminal, perdonad el ruido.", "봉 디아, 루카스! 잘 들려요? 터미널에 있어서요, 시끄러워서 미안해요."),
(L, "Te oímos perfectamente, Jordi. Estoy con Ramón, nuestro director financiero, y con Pepe, el jefe de planta.", "아주 잘 들려요, 조르디. 재무이사 라몬, 공장장 페페랑 같이 있어요."),
(J, "Hola a todos. Pepe, ¿tú no eras el del Villarreal?", "다들 안녕하세요. 페페, 비야레알 팬 그분 아니에요?"),
(P, "El mismo. Y tú el del Valencia. No empecemos.", "바로 나야. 그리고 넌 발렌시아 팬이고. 시작하지 말자."),
(L, "Jordi, como te escribí ayer: sesenta mil metros cuadrados de porcelánico, sesenta por ciento veinte, nueve milímetros, de Onda a Monterrey.", "조르디, 어제 메일에 쓴 대로예요. 자기질 타일 6만㎡, 60×120, 두께 9mm, 온다에서 몬테레이까지."),
(J, "Sí, lo he visto. Primera pregunta: ¿cuánto pesa el metro cuadrado?", "네, 봤어요. 첫 질문: ㎡당 무게가 얼마죠?"),
(P, "Con el embalaje, unos veinte kilos.", "포장 포함해서 20킬로쯤."),
(J, "Entonces olvidaos del contenedor de cuarenta pies. Con la cerámica, el contenedor se llena por peso, no por volumen.", "그럼 40피트 컨테이너는 잊으세요. 타일은 부피가 아니라 무게로 컨테이너가 차거든요."),
(R, "¿Y eso cuántos metros son?", "그게 ㎡로는 몇이죠?"),
(J, "En un veinte pies podéis cargar unos veintiséis mil kilos. Veintiséis mil entre veinte: mil trescientos metros por contenedor.", "20피트 하나에 2만 6천 킬로쯤 실을 수 있어요. 2만 6천 나누기 20, 컨테이너당 1,300㎡."),
(L, "Sesenta mil entre mil trescientos... unos cuarenta y seis contenedores.", "6만 나누기 1,300… 컨테이너 약 46개네요."),
(J, "Cuarenta y seis veinte pies. Eso ya es un cliente serio. Me gusta.", "20피트 46개. 그 정도면 진지한 고객이죠. 좋네요."),
(R, "¿Y habrá contenedores disponibles? Con tanto volumen...", "컨테이너는 구할 수 있을까요? 물량이 이렇게 많은데…"),
(J, "No los mandaríais todos a la vez. Lo normal sería hacerlo en varios embarques: ocho o diez contenedores por semana.", "한꺼번에 보내진 않을 거예요. 보통은 여러 번에 나눠 선적하죠. 주에 8개에서 10개씩."),
(P, "Diez contenedores por semana son trece mil metros. Eso lo cargamos sin problema.", "주에 컨테이너 10개면 1만 3천㎡. 그건 문제없이 실어."),
(L, "Bien. Vamos a los costes. Desde Onda hasta el barco, ¿cuánto?", "좋아요. 비용으로 가죠. 온다에서 배까지는 얼마예요?"),
(J, "Transporte de Onda al puerto, unos trescientos cincuenta euros por contenedor. Manipulación en la terminal y despacho de exportación, unos doscientos cincuenta. Seiscientos en total.", "온다에서 항구까지 운송이 컨테이너당 350유로쯤. 터미널 하역과 수출 통관이 250유로쯤. 합계 600."),
(L, "Seiscientos entre mil trescientos metros... cuarenta y seis céntimos por metro.", "600을 1,300㎡로 나누면… ㎡당 46센트."),
(R, "(con la calculadora) Cero coma cuarenta y seis. Así que el precio FOB Valencia sería trece cuarenta y cinco más cero cuarenta y seis: trece noventa y uno.", "(계산기를 두드리며) 0.46. 그러니까 FOB 발렌시아 가격은 13.45 더하기 0.46, 13.91이 되겠군."),
(L, "Lo dejamos en trece noventa. FOB significa que la mercancía viaja por nuestra cuenta hasta que está a bordo del barco en Valencia.", "13.90으로 하죠. FOB는 발렌시아에서 물건이 배에 실릴 때까지 우리가 비용과 위험을 진다는 뜻이에요."),
(J, "Exacto. Y luego viene el flete marítimo de Valencia a Altamira. Ahora mismo, mil novecientos cincuenta euros por contenedor de veinte pies, con todos los recargos.", "맞아요. 그다음은 발렌시아에서 알타미라까지 해상 운임이에요. 지금은 20피트 컨테이너당 1,950유로, 할증료 다 포함해서요."),
(P, "¿Altamira? ¿Y eso dónde está?", "알타미라? 그게 어디야?"),
(J, "En el golfo de México, en Tamaulipas. Es el puerto más cercano a Monterrey para los barcos que vienen de Europa. Unos dieciocho o veinte días de travesía.", "멕시코만, 타마울리파스주에 있어요. 유럽에서 오는 배에게는 몬테레이에서 제일 가까운 항구죠. 항해 18일에서 20일 정도."),
(L, "¿Y el seguro de la mercancía?", "화물 보험은요?"),
(J, "Más o menos un tres por mil del valor. Para un contenedor de unos dieciocho mil euros, unos cincuenta y cinco euros.", "화물 가액의 0.3% 정도요. 1만 8천 유로짜리 컨테이너면 55유로쯤."),
(R, "(teclea) Flete: mil novecientos cincuenta entre mil trescientos, uno cincuenta. Seguro: cuatro céntimos. CIF Altamira: trece noventa más uno cincuenta y cuatro... quince cuarenta y cuatro.", "(계산기를 두드리며) 운임은 1,950 나누기 1,300, 1.50. 보험은 4센트. CIF 알타미라는 13.90 더하기 1.54… 15.44."),
(L, "Quince cuarenta y cinco, redondeando. CIF: coste, seguro y flete pagados hasta el puerto de destino.", "반올림해서 15.45. CIF는 목적항까지 원가, 보험료, 운임을 우리가 지불하는 조건이에요."),
(P, "¿Y de Altamira a Monterrey? ¿Van andando?", "알타미라에서 몬테레이까지는? 걸어가?"),
(J, "(ríe) En camión. Unos quinientos kilómetros. Descarga en el puerto de Altamira, unos cuatrocientos euros; camión hasta Monterrey, unos mil cien. Mil quinientos por contenedor.", "(웃으며) 트럭으로요. 500킬로쯤이에요. 알타미라항 하역이 400유로쯤, 몬테레이까지 트럭이 1,100유로쯤. 컨테이너당 1,500."),
(L, "Mil quinientos entre mil trescientos: uno quince. DAP Monterrey: quince cuarenta y cinco más uno quince... dieciséis sesenta.", "1,500 나누기 1,300은 1.15. DAP 몬테레이는 15.45 더하기 1.15… 16.60."),
(R, "Dieciséis sesenta. Casi lo mismo que nuestra tarifa oficial en España. Qué casualidad.", "16.60. 스페인 공식 가격표랑 거의 같네. 우연치고는."),
(L, "Jordi, en DAP, ¿quién paga los aranceles y el IVA mexicano?", "조르디, DAP에서는 관세와 멕시코 부가세를 누가 내요?"),
(J, "El comprador. DAP es entregado en el lugar convenido, sin despachar en importación. Los impuestos y el despacho en México los paga la señora Garza.", "구매자요. DAP는 수입 통관 없이 합의한 장소에 인도하는 조건이에요. 멕시코 쪽 세금과 통관은 가르사 씨가 내요."),
(L, "¿Y cuánto tarda todo, de la fábrica a la obra?", "공장에서 현장까지 전부 얼마나 걸려요?"),
(J, "Contad cinco semanas: unos días hasta el barco, tres semanas de mar y una semana entre puerto, aduana y camión.", "5주로 잡으세요. 배까지 며칠, 바다에서 3주, 항구·세관·트럭에 1주."),
(R, "Cinco semanas con nuestro dinero flotando en el agua. ¿Y cuánto es el arancel para baldosas españolas?", "우리 돈이 5주 동안 물 위에 떠 있는 거군. 그런데 스페인 타일 관세는 얼마죠?"),
(J, "Eso no os lo digo yo, que luego me equivoco y me matáis. Hay que confirmarlo con el agente aduanal de ella en México. Depende de la clasificación del producto y del certificado de origen.", "그건 제가 말 안 할게요. 틀리면 저 죽이실 거잖아요. 멕시코에 있는 그분 관세사한테 확인해야 해요. 제품 분류랑 원산지 증명서에 따라 달라요."),
(L, "Entonces en la oferta pondremos: «aranceles e impuestos de importación por cuenta del comprador, a confirmar con su agente aduanal».", "그럼 견적서에 이렇게 쓰죠. '수입 관세 및 세금은 구매자 부담, 귀사 관세사와 확인 요망'."),
(J, "Perfecto. Y una cosa más: los fletes cambian cada semana. Poned una validez corta. Treinta días, como mucho.", "완벽해요. 하나 더요. 운임은 매주 바뀌어요. 유효기간을 짧게 두세요. 길어야 30일."),
(R, "Treinta días. Apuntado.", "30일. 적었어."),
(J, "Os lo mando todo por escrito esta tarde. Y Pepe... este año bajáis a Segunda, ¿eh?", "오늘 오후에 전부 서면으로 보낼게요. 그리고 페페… 올해는 2부로 강등이죠?"),
(P, "¡Bajarás tú! Adéu, Jordi.", "강등은 너나 해! 잘 가, 조르디."),
(None, "Lucas cuelga. En la pizarra, debajo de la línea, quedan cuatro cifras escritas en azul.", "루카스가 전화를 끊는다. 칠판의 선 아래에 파란색으로 쓴 숫자 네 개가 남아 있다."),

("#", "Escena 3 · 13:15 · Sala de reuniones", "장면 3 · 오후 1시 15분 · 회의실"),
(L, "Bueno, resumen. EXW Onda, trece veinte. FOB Valencia, trece noventa. CIF Altamira, quince cuarenta y cinco. DAP Monterrey, dieciséis sesenta.", "자, 정리하죠. EXW 온다 13.20, FOB 발렌시아 13.90, CIF 알타미라 15.45, DAP 몬테레이 16.60."),
(R, "Para ella, el más barato es el EXW, claro. Pero también el que más trabajo le da.", "그녀에게 제일 싼 건 당연히 EXW지. 하지만 제일 손이 많이 가는 것도 그거고."),
(P, "Y el más caro es el DAP, pero se lo dejamos en la puerta de la obra.", "제일 비싼 건 DAP지만 공사장 문 앞까지 갖다주는 거고."),
(L, "Propongo ofrecerle dos opciones: CIF Altamira y DAP Monterrey. Que elija ella.", "두 가지 옵션을 제안하죠. CIF 알타미라와 DAP 몬테레이. 그녀가 고르게 하고요."),
(R, "¿Y si el italiano le ofrece algo más barato?", "이탈리아 쪽이 더 싸게 제시하면?"),
(L, "Aunque los italianos tienen muy buen diseño, tienen un problema: desde Génova o desde La Spezia el flete a México no es más barato que desde Valencia.", "이탈리아 회사들이 디자인은 아주 좋지만 문제가 하나 있어요. 제노바나 라스페치아에서 멕시코로 가는 운임이 발렌시아보다 싸지 않다는 거예요."),
(R, "Aunque tienes razón con el flete, ellos fabrican más barato. Tienen hornos más nuevos.", "운임은 네 말이 맞지만, 그쪽은 더 싸게 만들어. 가마가 더 새것이거든."),
(P, "Más nuevos, sí. Mejores, no. El horno más fino de toda la provincia es nuestro número dos. Lo ajusté yo.", "더 새것이긴 하지. 더 좋진 않아. 이 주 전체에서 제일 섬세한 가마는 우리 2호기야. 내가 손봤거든."),
(L, "(sonríe) Lo pondré en la oferta: «fabricado en el horno más fino de Castellón».", "(미소 지으며) 견적서에 쓸게요. '카스테욘에서 가장 섬세한 가마에서 생산'."),
(R, "Hay otra cosa: el margen. A trece veinte en fábrica ganamos tres ochenta por metro. Por sesenta mil metros, son doscientos veintiocho mil euros de margen bruto.", "다른 것도 있어. 마진. 공장 출고 13.20이면 ㎡당 3.80을 벌어. 6만㎡면 매출총이익이 22만 8천 유로야."),
(L, "Sería la operación más rentable del año.", "올해 가장 수익성 높은 거래가 될 거예요."),
(R, "Lo sería, si la cobramos. No te olvides de la caja azul.", "돈을 받는다면 그렇겠지. 파란 상자 잊지 마."),
(L, "No me olvido. El informe comercial lo pedí el lunes. Llega el viernes.", "안 잊었어요. 신용 보고서는 월요일에 신청했어요. 금요일에 와요."),
(P, "Una pregunta de fábrica: ¿de dónde salen los sesenta mil metros? Porque el horno tres está frío.", "공장 쪽 질문 하나. 6만㎡는 어디서 나와? 3호기는 식어 있잖아."),
(L, "Del almacén. Según los datos de Amparo, del lote de mármol blanco hay sesenta y dos mil metros. Es el mismo tono que las muestras que le gustaron a Alejandra.", "창고에서요. 암파로 데이터에 따르면 흰 대리석 로트가 6만 2천㎡ 있어요. 알레한드라가 마음에 들어 한 샘플과 같은 색조예요."),
(P, "El lote M-14.", "M-14 로트로군."),
(L, "Ese. Si lo vendemos, vaciamos almacén, despertamos el dinero dormido y no tenemos que fabricar nada.", "그거요. 그걸 팔면 창고도 비우고, 잠자는 돈도 깨우고, 새로 만들 것도 없어요."),
(R, "Eso sí que me gusta. Vender stock es lo más barato que hay.", "그건 정말 마음에 드네. 재고를 파는 게 제일 싸게 먹히거든."),
(L, "Falta una cosa: la placa grande para el vestíbulo del hotel. Alejandra quiere el mismo mármol en ciento veinte por doscientos sesenta.", "하나 남았어요. 호텔 로비용 대형 판. 알레한드라는 같은 대리석을 120×260으로 원해요."),
(P, "Esa no está en stock. Esa hay que fabricarla. Y en el horno dos solo puedo meterla los jueves.", "그건 재고가 없어. 새로 만들어야 해. 그리고 2호기에선 목요일에만 넣을 수 있어."),
(R, "¿Y a qué precio?", "가격은?"),
(L, "Le daremos un precio aparte, la semana que viene. Son pocos metros, unos dos mil.", "다음 주에 따로 가격을 줄 거예요. 물량이 적어요, 2천㎡쯤."),
(P, "Pocos metros, pero son las piezas más difíciles de toda la fábrica. Que no se te olvide en el precio.", "물량은 적어도 공장 전체에서 제일 까다로운 제품이야. 가격에 반영하는 거 잊지 마."),
(L, "No se me olvida: precio de pieza difícil. Lo calculamos contigo el lunes.", "안 잊어요. 까다로운 제품 가격. 월요일에 페페랑 같이 계산하죠."),
(None, "Se abre la puerta. Entra Amparo, con la maleta todavía en la mano: acaba de llegar de Barcelona. Mira la pizarra, las cifras y la palabra «M-14» rodeada con un círculo.", "문이 열린다. 아직 여행 가방을 든 채 암파로가 들어온다. 바르셀로나에서 막 돌아온 참이다. 그녀는 칠판과 숫자들, 그리고 동그라미 친 'M-14'를 본다."),
(A, "¿Qué es esto?", "이게 뭐야?"),
(L, "Amparo, hola. Te iba a llamar esta tarde. Estamos preparando la oferta para Monterrey.", "암파로, 안녕. 오늘 오후에 전화하려고 했어. 몬테레이 견적을 준비하고 있어."),
(A, "Ya lo veo. Con mi lote.", "보이네. 내 로트로."),
(L, "Con el lote M-14. Sesenta y dos mil metros. Son tus datos.", "M-14 로트로. 6만 2천㎡. 네 데이터야."),
(A, "Mis datos dicen cuántos metros hay. No dicen que estén libres.", "내 데이터는 몇 ㎡가 있는지 말해 줄 뿐이야. 비어 있다고는 안 해."),
(R, "¿No están libres?", "남는 게 아니라고?"),
(A, "Esta mañana, en Barcelona, he cerrado con BricoHogar la promoción de primavera. Treinta y cinco mil metros del M-14, reservados para sus tiendas en mayo.", "오늘 아침 바르셀로나에서 브리코오가르와 봄 프로모션을 확정했어요. M-14 3만 5천㎡, 5월 매장용으로 잡아 뒀어요."),
(P, "Treinta y cinco mil...", "3만 5천이라…"),
(L, "Treinta y cinco mil de sesenta y dos. Quedan veintisiete mil.", "6만 2천 중 3만 5천이면 2만 7천이 남네."),
(A, "Veintisiete mil no son sesenta mil. Hasta Pepe sabe restar.", "2만 7천은 6만이 아니야. 페페도 뺄셈은 할 줄 알아."),
(P, "Oye, que yo resto mejor que nadie.", "이봐, 뺄셈은 내가 누구보다 잘해."),
(L, "¿Lo has cerrado? ¿Sin hablar con nadie?", "확정했다고? 아무랑도 상의 안 하고?"),
(A, "¿Sin hablar con nadie? Tú has preparado una oferta de sesenta mil metros sin hablar conmigo.", "아무랑도 상의 안 하고? 너야말로 나랑 한마디 상의도 없이 6만㎡짜리 견적을 만들었잖아."),
(L, "Tienes razón. Debería haberte llamado antes. Pero BricoHogar paga doce veintinueve y México, trece veinte.", "네 말이 맞아. 먼저 전화했어야 했어. 하지만 브리코오가르는 12.29를 내고 멕시코는 13.20을 내."),
(A, "BricoHogar lleva veinte años pagando. Tu señora de Monterrey todavía no ha pagado ni un euro.", "브리코오가르는 20년째 돈을 내 왔어. 네 몬테레이 아주머니는 아직 1유로도 안 냈고."),
(R, "(en voz baja) En eso tiene razón.", "(작은 목소리로) 그 점은 맞는 말이야."),
(L, "Ramón, esta mañana has dicho que vender stock es lo más barato que hay.", "라몬, 오늘 아침에 재고를 파는 게 제일 싸게 먹힌다고 했잖아요."),
(R, "Y lo mantengo. Pero un acuerdo cerrado vale más que una oferta sin respuesta.", "그 말은 지금도 유효해. 하지만 확정된 거래가 답 없는 견적보다는 값어치가 있지."),
(A, "Gracias, Ramón.", "고마워요, 라몬."),
(L, "¿Cerrado? ¿Ya has firmado?", "확정? 벌써 서명했어?"),
(A, "He dado mi palabra. Aquí es lo mismo. Así que esa oferta no sale con el M-14. Ni un metro. Lucas, la respuesta es no.", "약속했어. 여기선 그게 같은 거야. 그러니까 그 견적은 M-14로는 안 나가. 1㎡도. 루카스, 대답은 '아니'야."),
(None, "Amparo deja la maleta junto a la puerta y sale. Nadie dice nada. Pepe borra despacio el círculo de la pizarra.", "암파로가 여행 가방을 문 옆에 두고 나간다. 아무도 말이 없다. 페페가 칠판의 동그라미를 천천히 지운다."),
]

